import type { BankQuestion } from "@/lib/bank";

/** Chemical and Ionic Equilibrium (Chemistry (JEE/NEET)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-chemical-equilibrium-1","question":"The pH of a 0.01 M HCl solution is:","options":["1","2","12","0.01"],"answer":1,"explanation":"HCl is a strong acid, so [H⁺] = 10⁻² M and pH = −log(10⁻²) = 2.","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-equilibrium-2","question":"For the reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the value of Δn_g used in Kp = Kc(RT)^Δn is:","options":["+2","0","−1","−2"],"answer":3,"explanation":"Δn_g = moles of gaseous products − moles of gaseous reactants = 2 − (1 + 3) = −2, so Kp = Kc(RT)⁻².","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-3","question":"The conjugate base of HSO₄⁻ is:","options":["SO₄²⁻","H₂SO₄","HSO₃⁻","H₃O⁺"],"answer":0,"explanation":"A conjugate base is formed by removing one proton: HSO₄⁻ → SO₄²⁻ + H⁺. H₂SO₄ is the conjugate acid of HSO₄⁻.","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-equilibrium-4","question":"For the exothermic reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g), raising the temperature at constant pressure will:","options":["Shift the equilibrium forward and increase Kc","Shift the equilibrium backward and decrease Kc","Shift the equilibrium backward but leave Kc unchanged","Have no effect on the equilibrium"],"answer":1,"explanation":"By Le Chatelier's principle, heating favours the endothermic (backward) direction. Unlike changes in pressure or concentration, a change in temperature also changes the value of K: for an exothermic reaction K decreases on heating.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-equilibrium-5","question":"The pH of a 0.001 M NaOH solution at 25 °C is:","options":["3","13","1","11"],"answer":3,"explanation":"[OH⁻] = 10⁻³ M, so pOH = 3 and pH = 14 − 3 = 11. Answering 3 confuses pOH with pH.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-equilibrium-6","question":"The solubility product of AgCl is 1 × 10⁻¹⁰ at 25 °C. Its molar solubility in pure water is:","options":["10⁻²⁰ M","10⁻¹⁰ M","10⁻⁵ M","2 × 10⁻⁵ M"],"answer":2,"explanation":"AgCl ⇌ Ag⁺ + Cl⁻; Ksp = s² = 10⁻¹⁰, so s = 10⁻⁵ mol/L.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-7","question":"The degree of dissociation of a 0.1 M weak monobasic acid with Ka = 1 × 10⁻⁵ is:","options":["0.1%","10%","0.01%","1%"],"answer":3,"explanation":"Ostwald's dilution law: α = √(Ka/C) = √(10⁻⁵/10⁻¹) = √10⁻⁴ = 0.01, i.e. 1%.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-8","question":"If the reaction quotient Q is less than the equilibrium constant K for a reaction, then:","options":["The reaction is at equilibrium","The reaction proceeds in the forward direction to reach equilibrium","The reaction proceeds in the backward direction to reach equilibrium","The reaction cannot occur"],"answer":1,"explanation":"Q < K means the product-to-reactant ratio is below its equilibrium value, so more product must form: the net reaction goes forward until Q = K.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-equilibrium-9","question":"Which of the following salts gives a basic aqueous solution?","options":["NH₄Cl","NaCl","CH₃COONa","NH₄NO₃"],"answer":2,"explanation":"CH₃COONa is a salt of a weak acid and strong base: CH₃COO⁻ hydrolyses to give OH⁻ (pH > 7). NH₄Cl and NH₄NO₃ give acidic solutions; NaCl does not hydrolyse.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-equilibrium-10","question":"The pH of a 0.01 M solution of a weak monobasic acid HA (Ka = 4 × 10⁻⁶) is (log 2 = 0.3):","options":["3.7","4.3","3.3","4.0"],"answer":0,"explanation":"[H⁺] = √(Ka × C) = √(4 × 10⁻⁶ × 10⁻²) = √(4 × 10⁻⁸) = 2 × 10⁻⁴ M. pH = 4 − log 2 = 4 − 0.3 = 3.7.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-11","question":"A buffer contains 0.1 M CH₃COOH and 1.0 M CH₃COONa. If pKa of acetic acid is 4.74, the pH of the buffer is:","options":["3.74","4.74","6.74","5.74"],"answer":3,"explanation":"Henderson equation: pH = pKa + log([salt]/[acid]) = 4.74 + log(1.0/0.1) = 4.74 + 1 = 5.74.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-12","question":"1 mol of H₂ and 1 mol of I₂ are heated in a 1 L sealed vessel. At equilibrium 1.5 mol of HI is present. The value of Kc for H₂(g) + I₂(g) ⇌ 2HI(g) is:","options":["9","36","6","12"],"answer":1,"explanation":"Forming 1.5 mol HI consumes 0.75 mol each of H₂ and I₂, leaving 0.25 mol of each. Kc = (1.5)²/(0.25 × 0.25) = 2.25/0.0625 = 36.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-13","question":"PCl₅(g) ⇌ PCl₃(g) + Cl₂(g) is 50% dissociated at equilibrium at a total pressure of 3 atm. The value of Kp is:","options":["0.5 atm","1 atm","2 atm","3 atm"],"answer":1,"explanation":"Starting with 1 mol PCl₅ and α = 0.5: moles at equilibrium PCl₅ 0.5, PCl₃ 0.5, Cl₂ 0.5, total 1.5. Partial pressures: each = (0.5/1.5) × 3 = 1 atm. Kp = (1 × 1)/1 = 1 atm (equivalently Kp = α²P/(1 − α²) = 0.25 × 3/0.75 = 1).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-14","question":"The molar solubility of Ag₂CrO₄ in water is 1 × 10⁻⁴ M. Its solubility product is:","options":["1 × 10⁻¹²","4 × 10⁻¹²","4 × 10⁻⁸","2 × 10⁻¹²"],"answer":1,"explanation":"Ag₂CrO₄ ⇌ 2Ag⁺ + CrO₄²⁻: [Ag⁺] = 2s, [CrO₄²⁻] = s. Ksp = (2s)²(s) = 4s³ = 4 × (10⁻⁴)³ = 4 × 10⁻¹². Using s² gives the wrong 10⁻⁸.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-15","question":"The solubility of AgCl (Ksp = 1 × 10⁻¹⁰) in 0.1 M NaCl solution is:","options":["10⁻¹¹ M","10⁻¹⁰ M","10⁻⁹ M","10⁻⁵ M"],"answer":2,"explanation":"Common-ion effect: [Cl⁻] ≈ 0.1 M from NaCl, so s × 0.1 = 10⁻¹⁰ and s = 10⁻⁹ M, far below the 10⁻⁵ M solubility in pure water.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-16","question":"50 mL of 0.2 M HCl is mixed with 50 mL of 0.1 M NaOH. The pH of the resulting solution is (log 2 = 0.3):","options":["1.0","1.3","1.7","2.0"],"answer":1,"explanation":"H⁺ = 0.01 mol, OH⁻ = 0.005 mol; excess H⁺ = 0.005 mol in 100 mL = 0.05 M. pH = −log(5 × 10⁻²) = 2 − log 5 = 2 − 0.7 = 1.3.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-17","question":"If the equilibrium constant for N₂(g) + 3H₂(g) ⇌ 2NH₃(g) is 4 at a given temperature, the equilibrium constant for NH₃(g) ⇌ ½N₂(g) + 3/2 H₂(g) at the same temperature is:","options":["0.25","0.5","2","4"],"answer":1,"explanation":"Reversing a reaction gives 1/K = 0.25, and halving the coefficients takes the square root: √0.25 = 0.5.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-18","question":"An inert gas is added to the equilibrium PCl₅(g) ⇌ PCl₃(g) + Cl₂(g). Which statement is correct?","options":["No shift at constant volume; forward shift at constant pressure","Forward shift in both cases","Backward shift at constant pressure","No shift in either case"],"answer":0,"explanation":"At constant volume the partial pressures of the reacting gases are unchanged, so nothing happens. At constant pressure the total volume must increase, which lowers each partial pressure and favours the side with more gas moles (forward).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-19","question":"The pH of a 0.1 M solution of sodium acetate is (Ka of acetic acid = 1 × 10⁻⁵):","options":["5","7","9","11"],"answer":2,"explanation":"Salt of weak acid and strong base: pH = 7 + ½(pKa + log C) = 7 + ½(5 + log 0.1) = 7 + ½(5 − 1) = 9. (Check: Kh = Kw/Ka = 10⁻⁹, [OH⁻] = √(Kh × C) = √10⁻¹⁰ = 10⁻⁵, pOH = 5.)","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-20","question":"For 0.1 M ammonium acetate solution (Ka of CH₃COOH = Kb of NH₄OH = 1.8 × 10⁻⁵), the pH and the effect of dilution on it are:","options":["7.0, and it does not change on dilution","7.0, and it rises on dilution","5.3, and it rises on dilution","8.7, and it falls on dilution"],"answer":0,"explanation":"For a salt of a weak acid and weak base, pH = 7 + ½(pKa − pKb). With pKa = pKb, pH = 7.0, and since the expression contains no concentration term, dilution does not change it.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-21","question":"1 L of a buffer contains 0.1 mol of a weak acid HA (pKa = 5) and 0.1 mol of NaA. 0.05 mol of NaOH is added without change in volume. The new pH is (log 3 = 0.48):","options":["5.00","4.52","5.30","5.48"],"answer":3,"explanation":"OH⁻ converts 0.05 mol HA into A⁻: HA = 0.05 mol, A⁻ = 0.15 mol. pH = pKa + log(0.15/0.05) = 5 + log 3 = 5.48. The original pH was 5.00.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-22","question":"How many of the following statements are correct? (A) A catalyst increases the equilibrium constant of a reaction. (B) For an endothermic reaction, K increases with temperature. (C) At equilibrium ΔG = 0 and ΔG° = −RT ln K. (D) Increasing the pressure shifts a gaseous equilibrium towards the side with fewer moles of gas.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A) false: a catalyst speeds up both directions equally and only shortens the time to reach equilibrium. (B), (C) and (D) are true. Three are correct.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-chemical-equilibrium-23","question":"Assertion (A): The pH of a 1 × 10⁻⁸ M HCl solution is slightly less than 7, not 8. Reason (R): In such a dilute solution the H⁺ contributed by the self-ionisation of water cannot be neglected.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Water alone gives 10⁻⁷ M H⁺, comparable to the 10⁻⁸ M from the acid. Solving the full charge balance gives [H⁺] ≈ 1.05 × 10⁻⁷ M, pH ≈ 6.98. An acid solution can never have pH > 7 at 25 °C.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-24","question":"Equal volumes of 2 × 10⁻⁴ M AgNO₃ and 2 × 10⁻⁴ M NaCl are mixed (Ksp of AgCl = 1 × 10⁻¹⁰). Will AgCl precipitate?","options":["Yes, because Q = 10⁻⁸ exceeds Ksp","No, because Q = 10⁻⁸ is less than Ksp","Yes, because Q = 4 × 10⁻⁸ exceeds Ksp","No, because the concentrations halve on mixing"],"answer":0,"explanation":"Mixing equal volumes halves each concentration to 1 × 10⁻⁴ M. Q = [Ag⁺][Cl⁻] = 10⁻⁴ × 10⁻⁴ = 10⁻⁸ > Ksp (10⁻¹⁰), so AgCl precipitates. Forgetting the dilution gives 4 × 10⁻⁸, the wrong value of Q.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-25","question":"The equilibrium constant of a reaction is 1 × 10³ at 300 K. The standard Gibbs energy change ΔG° is (R = 8.3 J/K/mol, 2.303 log x = ln x):","options":["−17.2 kJ/mol","+17.2 kJ/mol","−5.7 kJ/mol","−51.6 kJ/mol"],"answer":0,"explanation":"ΔG° = −2.303 RT log K = −2.303 × 8.3 × 300 × log(10³) = −2.303 × 8.3 × 300 × 3 ≈ −17,200 J/mol = −17.2 kJ/mol. A negative ΔG° matches K > 1.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-26","question":"The vapour density of partially dissociated N₂O₄ (N₂O₄ ⇌ 2NO₂) at equilibrium is 40. The degree of dissociation of N₂O₄ is:","options":["0.10","0.15","0.20","0.30"],"answer":1,"explanation":"Molar mass of N₂O₄ = 92, so initial vapour density D = 46. For dissociation into 2 particles, α = (D − d)/d = (46 − 40)/40 = 0.15.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-27","question":"Match the solution (Column I) with its pH at 25 °C (Column II). (a) 0.1 M HCl, (b) 0.1 M NaOH, (c) 0.1 M CH₃COOH (Ka = 10⁻⁵), (d) 0.1 M CH₃COONa (Ka of CH₃COOH = 10⁻⁵). (1) 9; (2) 1; (3) 13; (4) 3.","options":["a-2, b-3, c-1, d-4","a-3, b-2, c-4, d-1","a-2, b-1, c-4, d-3","a-2, b-3, c-4, d-1"],"answer":3,"explanation":"0.1 M HCl: pH 1. 0.1 M NaOH: pOH 1, pH 13. 0.1 M CH₃COOH: [H⁺] = √(10⁻⁵ × 10⁻¹) = 10⁻³, pH 3. 0.1 M CH₃COONa: pH = 7 + ½(5 − 1) = 9.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-28","question":"The solubility of which of the following sparingly soluble salts increases the most when the pH of the solution is lowered?","options":["AgCl","BaSO₄","CaCO₃","AgBr"],"answer":2,"explanation":"CO₃²⁻ is the anion of a weak acid; added H⁺ removes it as HCO₃⁻/H₂CO₃, pulling CaCO₃ ⇌ Ca²⁺ + CO₃²⁻ to the right. Cl⁻, Br⁻ and SO₄²⁻ are anions of strong acids and are barely protonated.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-29","question":"A solution is 0.1 M in both Cl⁻ and I⁻. AgNO₃ is added slowly (Ksp: AgCl = 1 × 10⁻¹⁰, AgI = 1 × 10⁻¹⁶). The concentration of I⁻ remaining in solution when AgCl just begins to precipitate is:","options":["10⁻⁷ M","10⁻⁶ M","10⁻⁹ M","10⁻¹⁶ M"],"answer":0,"explanation":"AgI precipitates first. AgCl starts when [Ag⁺] = Ksp/[Cl⁻] = 10⁻¹⁰/0.1 = 10⁻⁹ M. At that [Ag⁺], [I⁻] = 10⁻¹⁶/10⁻⁹ = 10⁻⁷ M, so I⁻ is almost completely removed before any AgCl forms.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-30","question":"2 mol of A(g) is placed in a 10 L vessel and the equilibrium 2A(g) ⇌ B(g) + C(g) is established with 25% of A dissociated. The value of Kc is:","options":["1/36","1/16","1/9","1/4"],"answer":0,"explanation":"A dissociated = 0.5 mol, so at equilibrium A = 1.5 mol, B = C = 0.25 mol. Concentrations: A 0.15 M, B = C = 0.025 M. Kc = (0.025 × 0.025)/(0.15)² = (0.025/0.15)² = (1/6)² = 1/36. Since Δn = 0, the volume cancels and the same Kc would result in any vessel.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-31","question":"The unit of Kc for the reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g) is:","options":["No unit","mol² L⁻²","mol L⁻¹","L² mol⁻²"],"answer":3,"explanation":"Kc = [NH₃]²/([N₂][H₂]³) has units (mol/L)^(2 − 4) = (mol/L)⁻² = L² mol⁻².","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-32","question":"For N₂O₄(g) ⇌ 2NO₂(g) at equilibrium, increasing the total pressure by compressing the mixture at constant temperature:","options":["Shifts the equilibrium towards NO₂","Shifts the equilibrium towards N₂O₄","Changes the value of Kp","Has no effect on the equilibrium"],"answer":1,"explanation":"Compression favours the side with fewer gas moles (1 mol N₂O₄ vs 2 mol NO₂). Kp depends only on temperature.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-33","question":"For a sparingly soluble salt CaF₂ with molar solubility s, the solubility product is:","options":["27s⁴","4s³","s²","2s³"],"answer":1,"explanation":"CaF₂ ⇌ Ca²⁺ + 2F⁻: Ksp = s(2s)² = 4s³.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-34","question":"Which of the following can act both as a Brønsted acid and as a Brønsted base?","options":["Cl⁻","CO₃²⁻","NH₄⁺","HCO₃⁻"],"answer":3,"explanation":"HCO₃⁻ can donate a proton (giving CO₃²⁻) or accept one (giving H₂CO₃). CO₃²⁻ and Cl⁻ only accept; NH₄⁺ only donates.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-35","question":"A buffer is 0.1 M in NH₄OH (Kb = 1.8 × 10⁻⁵, pKb = 4.74) and 0.1 M in NH₄Cl. Its pH at 25 °C is:","options":["7.00","9.74","9.26","4.74"],"answer":2,"explanation":"pOH = pKb + log([salt]/[base]) = 4.74 + 0 = 4.74, so pH = 14 − 4.74 = 9.26. 4.74 is pOH, not pH.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-36","question":"At a temperature where Kw = 1 × 10⁻¹³, the pH of pure water is:","options":["6.5, and the water is neutral","7.0, and the water is neutral","6.5, and the water is acidic","13, and the water is basic"],"answer":0,"explanation":"[H⁺] = [OH⁻] = √(10⁻¹³) = 10⁻⁶·⁵, pH = 6.5. Pure water is always neutral because [H⁺] = [OH⁻]; pH 7 is neutral only at 25 °C.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-37","question":"For 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), the ratio Kp/Kc equals:","options":["1","RT","(RT)²","(RT)⁻¹"],"answer":3,"explanation":"Kp = Kc(RT)^Δn with Δn = 2 − 3 = −1, so Kp/Kc = (RT)⁻¹.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-38","question":"The Ksp of a hydroxide M(OH)₂ is 4 × 10⁻¹². The pH at which M(OH)₂ just begins to precipitate from a 0.01 M solution of M²⁺ is (log 2 = 0.3):","options":["10.3","4.7","8.7","9.3"],"answer":3,"explanation":"[OH⁻]² = Ksp/[M²⁺] = 4 × 10⁻¹⁰, so [OH⁻] = 2 × 10⁻⁵ M, pOH = 4.7 and pH = 9.3. 4.7 is the pOH.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-39","question":"How many of the following statements are correct? (A) Kp = Kc when Δn(gas) = 0. (B) A buffer has its maximum buffer capacity when pH = pKa. (C) Adding NH₄Cl to aqueous NH₄OH decreases the degree of ionisation of NH₄OH. (D) The pH of 1 × 10⁻³ M H₂SO₄ (complete ionisation) is about 2.7.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. D: [H⁺] = 2 × 10⁻³ M, pH = 3 − 0.3 = 2.7. C is the common-ion effect.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-40","question":"For A ⇌ B, K₁ = 4, and for B ⇌ C, K₂ = 0.5 at the same temperature. The equilibrium constant for 2C ⇌ 2A is:","options":["2","4","0.25","0.5"],"answer":2,"explanation":"A ⇌ C: K = K₁K₂ = 2. Reversing: C ⇌ A, K = 0.5. Doubling the equation squares K: (0.5)² = 0.25.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-41","question":"The pH of an aqueous solution of a salt of a weak acid (pKa = 4.8) and a weak base (pKb = 4.2) at 25 °C is:","options":["7.3","6.7","8.0","7.0"],"answer":0,"explanation":"For such salts pH = 7 + ½(pKa − pKb) = 7 + ½(0.6) = 7.3, independent of concentration. The base is slightly stronger, so the solution is slightly basic.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-42","question":"The solubility of Ag₂CrO₄ (Ksp = 4 × 10⁻¹²) in 0.01 M AgNO₃ solution is:","options":["4 × 10⁻¹⁰ M","1 × 10⁻⁴ M","4 × 10⁻⁸ M","2 × 10⁻⁵ M"],"answer":2,"explanation":"With [Ag⁺] ≈ 0.01 M fixed by AgNO₃, s = [CrO₄²⁻] = Ksp/[Ag⁺]² = 4 × 10⁻¹²/10⁻⁴ = 4 × 10⁻⁸ M. 1 × 10⁻⁴ M is the solubility in pure water.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-43","question":"Assertion (A): The pH of 0.1 M CH₃COOH rises when solid CH₃COONa is dissolved in it. Reason (R): CH₃COONa is a salt of a strong acid and a weak base.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: the common ion CH₃COO⁻ suppresses ionisation of acetic acid, lowering [H⁺]. R is false: sodium acetate is a salt of a weak acid and a strong base.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-chemical-equilibrium-44","question":"N₂O₄ is 20% dissociated into NO₂ at equilibrium when the total pressure is 1 atm. The value of Kp for N₂O₄(g) ⇌ 2NO₂(g) is:","options":["0.25 atm","1/6 atm","0.04 atm","1/3 atm"],"answer":1,"explanation":"From 1 mol: N₂O₄ 0.8, NO₂ 0.4, total 1.2. p(NO₂) = 1/3, p(N₂O₄) = 2/3 atm. Kp = (1/3)²/(2/3) = 1/6 atm (also 4α²P/(1 − α²) = 0.16/0.96).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-45","question":"20 mL of 0.1 M Na₂CO₃ is titrated with 0.1 M HCl. The volumes of HCl needed to reach the phenolphthalein end point and the methyl orange end point (measured from the start) are:","options":["10 mL and 20 mL","20 mL and 20 mL","40 mL and 20 mL","20 mL and 40 mL"],"answer":3,"explanation":"Phenolphthalein decolourises when CO₃²⁻ → HCO₃⁻ (2 mmol HCl = 20 mL). Methyl orange changes only after HCO₃⁻ → H₂CO₃, needing another 20 mL, 40 mL in total.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-46", "question": "For the equilibrium H₂(g) + I₂(g) ⇌ 2HI(g), increasing the total pressure by compressing the mixture at constant temperature:", "options": ["Shifts the equilibrium to the right", "Shifts the equilibrium to the left", "Does not shift the equilibrium", "Increases the equilibrium constant"], "answer": 2, "explanation": "There are 2 mol of gas on each side (Δn = 0), so pressure has no effect on the position of equilibrium. K changes only with temperature.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-chemical-equilibrium-47", "question": "Which of the following is a Lewis acid?", "options": ["NH₃", "BF₃", "Cl⁻", "H₂O"], "answer": 1, "explanation": "A Lewis acid accepts an electron pair. Boron in BF₃ has only six electrons and an empty p orbital, so it accepts a pair. NH₃, Cl⁻ and H₂O all have lone pairs to donate (Lewis bases).", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-chemical-equilibrium-48", "question": "For the decomposition CaCO₃(s) ⇌ CaO(s) + CO₂(g), the equilibrium constant Kp is:", "options": ["p(CaO) × p(CO₂)/p(CaCO₃)", "1/p(CO₂)", "[CaO][CO₂]/[CaCO₃]", "p(CO₂)"], "answer": 3, "explanation": "Pure solids have constant activity (taken as 1) and do not appear in the expression, so Kp = p(CO₂). This is why the CO₂ pressure over heated limestone at a given temperature is fixed.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-49", "question": "The hydrogen ion concentration of a solution with pH 4.7 is (log 2 = 0.3):", "options": ["5 × 10⁻⁵ M", "2 × 10⁻⁵ M", "2 × 10⁻⁴ M", "4.7 × 10⁻⁵ M"], "answer": 1, "explanation": "[H⁺] = 10⁻⁴·⁷ = 10⁰·³ × 10⁻⁵ = 2 × 10⁻⁵ M.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-chemical-equilibrium-50", "question": "The molar solubility of AgCl is lowest in which of the following?", "options": ["Pure water", "0.1 M NaCl", "0.1 M CaCl₂", "0.1 M NaNO₃"], "answer": 2, "explanation": "By the common-ion effect, s = Ksp/[Cl⁻]. 0.1 M CaCl₂ supplies 0.2 M Cl⁻, more than 0.1 M NaCl, so solubility is lowest there. NaNO₃ has no common ion (it slightly raises solubility through ionic strength).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-51", "question": "The most suitable indicator for titrating aqueous ammonia (a weak base) with hydrochloric acid is:", "options": ["Methyl orange", "Phenolphthalein", "Either indicator works equally well", "No indicator can be used"], "answer": 0, "explanation": "At the equivalence point the solution contains NH₄Cl and is acidic (pH about 5–6). Methyl orange changes colour in the acidic range (3.1–4.4), on the steep part of the curve; phenolphthalein (8.3–10) would change too early.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-52", "question": "Equal volumes of two HCl solutions of pH 3 and pH 5 are mixed. The pH of the mixture is about:", "options": ["4.0", "3.0", "4.3", "3.3"], "answer": 3, "explanation": "[H⁺] = (10⁻³ + 10⁻⁵)/2 = 5.05 × 10⁻⁴ M, so pH = −log(5.05 × 10⁻⁴) ≈ 3.3. Averaging the pH values (giving 4.0) is the trap; pH is logarithmic.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-53", "question": "Kb of ammonia is 1.8 × 10⁻⁵ at 25 °C. The acid dissociation constant Ka of the ammonium ion is:", "options": ["1.8 × 10⁻⁹", "5.6 × 10⁻⁹", "5.6 × 10⁻¹⁰", "1.8 × 10⁻¹⁹"], "answer": 2, "explanation": "For a conjugate acid–base pair Ka × Kb = Kw, so Ka = 1 × 10⁻¹⁴/1.8 × 10⁻⁵ = 5.6 × 10⁻¹⁰.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-54", "question": "The Ksp of Mg(OH)₂ is 3.2 × 10⁻¹¹ at 25 °C. The pH of its saturated aqueous solution is (log 2 = 0.3):", "options": ["10.3", "10.6", "3.4", "11.0"], "answer": 1, "explanation": "Ksp = s(2s)² = 4s³ = 3.2 × 10⁻¹¹, so s³ = 8 × 10⁻¹² and s = 2 × 10⁻⁴ M. [OH⁻] = 2s = 4 × 10⁻⁴ M, pOH = 4 − 0.6 = 3.4, pH = 10.6. 10.3 uses [OH⁻] = s instead of 2s.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-55", "question": "In a 0.1 M solution of H₂S (Ka₁ = 1 × 10⁻⁷, Ka₂ = 1.3 × 10⁻¹³), the concentration of S²⁻ ions is approximately:", "options": ["1 × 10⁻⁴ M", "1 × 10⁻⁷ M", "1.3 × 10⁻¹⁷ M", "1.3 × 10⁻¹³ M"], "answer": 3, "explanation": "From the first step [H⁺] ≈ [HS⁻] ≈ √(10⁻⁷ × 0.1) = 10⁻⁴ M. In Ka₂ = [H⁺][S²⁻]/[HS⁻] the [H⁺] and [HS⁻] cancel, so [S²⁻] ≈ Ka₂ = 1.3 × 10⁻¹³ M. 1 × 10⁻⁴ M is [H⁺], not [S²⁻].", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-chemical-equilibrium-56", "question": "The equilibrium constant of a reaction rises from 10 at 300 K to 100 at 400 K. Assuming ΔH° is constant, its value is about (R = 8.314 J K⁻¹ mol⁻¹):", "options": ["+23.0 kJ mol⁻¹", "−23.0 kJ mol⁻¹", "+10.0 kJ mol⁻¹", "+2.3 kJ mol⁻¹"], "answer": 0, "explanation": "van 't Hoff: log(K₂/K₁) = (ΔH°/2.303R)(1/T₁ − 1/T₂). 1 = ΔH°/(19.15) × (1/300 − 1/400) = ΔH° × 8.33 × 10⁻⁴/19.15, so ΔH° = 2.30 × 10⁴ J ≈ +23.0 kJ. K rising with T means endothermic; +10.0 kJ forgets the factor 2.303.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-57", "question": "For A(g) + B(g) ⇌ C(g) + D(g), Kc = 4 at a certain temperature. If 1 mol each of A and B is placed in a 1 L vessel, the amount of C at equilibrium is:", "options": ["0.5 mol", "0.33 mol", "0.67 mol", "0.8 mol"], "answer": 2, "explanation": "x²/(1 − x)² = 4, so x/(1 − x) = 2 and x = 2/3 ≈ 0.67 mol. Check: (0.67)²/(0.33)² = 4.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-58", "question": "Which of the following mixtures acts as a buffer solution?", "options": ["50 mL of 0.1 M HCl + 50 mL of 0.1 M NaOH", "50 mL of 0.1 M CH₃COOH + 25 mL of 0.1 M NaOH", "50 mL of 0.1 M CH₃COOH + 50 mL of 0.1 M NaOH", "50 mL of 0.1 M NH₄OH + 50 mL of 0.1 M HCl"], "answer": 1, "explanation": "Half-neutralising acetic acid leaves 2.5 mmol CH₃COOH and 2.5 mmol CH₃COONa: a weak acid with its salt, i.e. a buffer (pH = pKa). The other mixtures are fully neutralised and contain only a salt (or salt and water), with no weak acid–conjugate base pair left.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-59", "question": "A 1 M solution of a weak acid (Ka = 1 × 10⁻⁵) is diluted 100 times. Its pH:", "options": ["Increases by 2", "Does not change", "Decreases by 1", "Increases by 1"], "answer": 3, "explanation": "For a weak acid [H⁺] = √(Ka c), so pH = ½(pKa − log c). Reducing c by 100 raises pH by ½ × 2 = 1 (from 2.5 to 3.5). An increase of 2 would apply to a strong acid.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-60", "question": "How many of the following statements are correct? (A) For PCl₅(g) ⇌ PCl₃(g) + Cl₂(g), adding Cl₂ at constant volume lowers the degree of dissociation of PCl₅. (B) Kp for CaCO₃(s) ⇌ CaO(s) + CO₂(g) does not depend on how much CaCO₃ is present. (C) The value of an equilibrium constant depends on the initial concentrations of the reactants. (D) For a system at equilibrium at constant T and P, ΔG = 0.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(A) true, by Le Chatelier (common product). (B) true; solids do not enter the expression. (C) false; K depends only on temperature (for a given equation). (D) true. Three are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-61", "question": "Solid NH₄HS is placed in a flask that already contains NH₃ at 0.6 atm. For NH₄HS(s) ⇌ NH₃(g) + H₂S(g), Kp = 0.16 atm². The total pressure at equilibrium is:", "options": ["0.8 atm", "1.4 atm", "1.0 atm", "0.4 atm"], "answer": 2, "explanation": "Let p = pressure of H₂S formed: (0.6 + p)p = 0.16, so p² + 0.6p − 0.16 = 0 and p = (−0.6 + 1.0)/2 = 0.2 atm. Total = (0.6 + 0.2) + 0.2 = 1.0 atm. Without the added NH₃ the total would be 0.8 atm.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-chemical-equilibrium-62", "question": "50 mL of 0.1 M CH₃COOH (pKa = 4.74) is titrated with 0.1 M NaOH. The pH after 25 mL and after 50 mL of NaOH have been added is respectively (log 5 = 0.70):", "options": ["4.74 and 7.00", "2.87 and 8.72", "4.74 and 9.37", "4.74 and 8.72"], "answer": 3, "explanation": "At 25 mL the acid is half-neutralised, so pH = pKa = 4.74. At 50 mL only CH₃COONa remains, 5 mmol in 100 mL = 0.05 M: pH = 7 + ½pKa + ½log c = 7 + 2.37 + ½(−1.30) = 8.72. The equivalence point is basic, not 7.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-chemical-equilibrium-63", "question": "Assertion (A): The pH of an aqueous solution of NaHCO₃ is almost independent of its concentration. Reason (R): For an amphiprotic anion such as HCO₃⁻, pH ≈ ½(pKa₁ + pKa₂).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "HCO₃⁻ can both lose and gain a proton; combining the two equilibria gives [H⁺] ≈ √(Ka₁Ka₂), which contains no concentration term (pH ≈ ½(6.35 + 10.33) ≈ 8.3). R correctly explains A.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-chemical-equilibrium-64", "question": "Match the 0.1 M aqueous solution (Column I) with the correct description (Column II). (a) NH₄Cl, (b) NaCl, (c) Na₂CO₃, (d) NaHSO₄. (1) Acidic, because the cation hydrolyses; (2) Neutral, no hydrolysis; (3) Basic, because the anion hydrolyses; (4) Acidic, because the anion itself ionises to give H⁺.", "options": ["a-4, b-2, c-3, d-1", "a-1, b-2, c-3, d-4", "a-1, b-3, c-2, d-4", "a-1, b-2, c-4, d-3"], "answer": 1, "explanation": "NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺ (acidic); NaCl comes from a strong acid and strong base (neutral); CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻ (basic); HSO₄⁻ is itself a fairly strong acid, HSO₄⁻ ⇌ H⁺ + SO₄²⁻. So a-1, b-2, c-3, d-4.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-65", "question": "Which of the following silver salts has the highest molar solubility in water? (Ksp: AgCl = 1.8 × 10⁻¹⁰, AgBr = 5 × 10⁻¹³, Ag₂CrO₄ = 1.1 × 10⁻¹², AgI = 8.3 × 10⁻¹⁷)", "options": ["AgCl", "AgBr", "Ag₂CrO₄", "AgI"], "answer": 2, "explanation": "For AgX, s = √Ksp: AgCl 1.3 × 10⁻⁵ M, AgBr 7 × 10⁻⁷ M, AgI 9 × 10⁻⁹ M. For Ag₂CrO₄, 4s³ = 1.1 × 10⁻¹², s = 6.5 × 10⁻⁵ M, the highest. Ksp values can be compared directly only for salts of the same formula type.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-66", "question": "The degree of dissociation of 0.1 M acetic acid (Ka = 1.8 × 10⁻⁵) in a solution that is also 0.1 M in HCl is about:", "options": ["1.34 × 10⁻²", "1.8 × 10⁻⁵", "4.2 × 10⁻³", "1.8 × 10⁻⁴"], "answer": 3, "explanation": "HCl fixes [H⁺] ≈ 0.1 M. Ka = [H⁺]·cα/(c(1 − α)) ≈ 0.1α, so α = 1.8 × 10⁻⁴. Without HCl, α = √(Ka/c) = 1.34 × 10⁻², about 75 times larger: the common-ion effect.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-67", "question": "For N₂(g) + O₂(g) ⇌ 2NO(g), Kc = 4 × 10⁻⁴ at a high temperature. If 1 mol each of N₂ and O₂ is heated in a 1 L vessel to this temperature, the equilibrium concentration of NO is about:", "options": ["0.02 M", "0.01 M", "0.04 M", "2 × 10⁻⁴ M"], "answer": 0, "explanation": "(2x)²/(1 − x)² = 4 × 10⁻⁴, so 2x/(1 − x) = 0.02. Since x is small, 2x ≈ 0.02 M = [NO]. 0.01 M is x itself, the amount of N₂ used, not [NO].", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-68", "question": "How many of the following statements are correct? (A) Water can act as a Lewis base. (B) BF₃ is a Brønsted acid. (C) The conjugate acid of a weak base is always a strong acid. (D) The pH of 1 × 10⁻³ M H₂SO₄ (fully ionised) is about 2.7 (log 2 = 0.3).", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(A) true; its oxygen donates lone pairs. (B) false; BF₃ has no proton to give (it is a Lewis acid). (C) false; NH₄⁺, the conjugate acid of weak NH₃, is itself a weak acid. (D) true; [H⁺] = 2 × 10⁻³ M, pH = 3 − 0.3 = 2.7. Two are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-69", "question": "At 25 °C, the fraction of water molecules that are ionised in pure water (density 1 g/mL, so [H₂O] ≈ 55.5 M) is about:", "options": ["1 × 10⁻⁷", "1 × 10⁻¹⁴", "1.8 × 10⁻⁹", "1.8 × 10⁻¹⁶"], "answer": 2, "explanation": "[H⁺] = 1 × 10⁻⁷ M of 55.5 M water, so the fraction = 10⁻⁷/55.5 = 1.8 × 10⁻⁹. 1.8 × 10⁻¹⁶ is the dissociation constant Kw/55.5, not the fraction ionised.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-70", "question": "Which of the following will NOT change the numerical value of Kc for N₂(g) + 3H₂(g) ⇌ 2NH₃(g)?", "options": ["Raising the temperature", "Adding an iron catalyst", "Lowering the temperature", "Writing the equation as ½N₂ + 3/2 H₂ ⇌ NH₃"], "answer": 1, "explanation": "A catalyst speeds up the forward and backward reactions equally and leaves K unchanged. K depends on temperature, and halving the equation gives K^½, a different number.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-equilibrium-71", "question": "Argon is added at constant total pressure to the equilibrium N₂(g) + 3H₂(g) ⇌ 2NH₃(g). The equilibrium:", "options": ["shifts towards N₂ and H₂", "is not disturbed at all", "shifts towards NH₃", "shifts towards NH₃ only if the reaction is exothermic"], "answer": 0, "explanation": "At constant pressure the added gas increases the volume and lowers every partial pressure, so the system moves to the side with more gas molecules (4 vs 2): NH₃ partly dissociates. 'No effect' is true only for addition at constant volume.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-72","question":"The pH of a 1 × 10⁻³ M aqueous solution of Ba(OH)₂ at 25 °C (complete dissociation, log 2 = 0.3) is:","options":["11.0","11.3","11.6","2.7"],"answer":1,"explanation":"[OH⁻] = 2 × 10⁻³ M, so pOH = 3 − 0.3 = 2.7 and pH = 14 − 2.7 = 11.3. Ignoring the two OH⁻ per formula unit gives 11.0, and stopping at pOH gives 2.7.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-73", "question": "Which of the following is the strongest Brønsted base?", "options": ["Cl⁻", "NO₃⁻", "CH₃COO⁻", "HSO₄⁻"], "answer": 2, "explanation": "The weaker the acid, the stronger its conjugate base. HCl, HNO₃ and H₂SO₄ are strong acids, so Cl⁻, NO₃⁻ and HSO₄⁻ are very weak bases, while acetic acid (pKa ≈ 4.76) is weak, making CH₃COO⁻ the strongest base here.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-74","question":"The molar solubility of Mg(OH)₂ (Ksp = 1.2 × 10⁻¹¹) in a buffer solution of pH 10 is:","options":["1.4 × 10⁻⁴ M","6.0 × 10⁻⁴ M","1.2 × 10⁻⁷ M","1.2 × 10⁻³ M"],"answer":3,"explanation":"The buffer fixes [OH⁻] = 10⁻⁴ M regardless of how much Mg(OH)₂ dissolves, so s = Ksp/[OH⁻]² = 1.2 × 10⁻¹¹/10⁻⁸ = 1.2 × 10⁻³ M. 1.4 × 10⁻⁴ M is the solubility in pure water (∛(Ksp/4)), which ignores the buffer.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-75", "question": "0.1 M acetic acid has a degree of dissociation α. To what concentration must it be diluted so that its degree of dissociation becomes 2α (α remains small)?", "options": ["0.05 M", "0.2 M", "0.025 M", "0.0125 M"], "answer": 2, "explanation": "Ostwald's dilution law for a weak acid: α ≈ √(Ka/C), so α ∝ 1/√C. Doubling α requires C to fall by a factor of 4: 0.1/4 = 0.025 M. Halving the concentration (0.05 M) would raise α only by √2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-76","question":"1 mol of A and 2 mol of B are placed in a 2 L vessel and the equilibrium A(g) + 2B(g) ⇌ C(g) is established with 0.5 mol of C present. The value of Kc is:","options":["4 L² mol⁻²","0.25 L² mol⁻²","2 L² mol⁻²","1 L² mol⁻²"],"answer":0,"explanation":"At equilibrium: A = 0.5 mol, B = 1.0 mol, C = 0.5 mol in 2 L, i.e. 0.25, 0.5 and 0.25 M. Kc = 0.25/(0.25 × 0.5²) = 4 L² mol⁻². Using moles instead of concentrations gives the trap value 1.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-77", "question": "The pH of a 0.01 M NH₄Cl solution at 25 °C is about (Kb of NH₃ = 1.8 × 10⁻⁵):", "options": ["5.63", "5.13", "8.37", "6.13"], "answer": 0, "explanation": "NH₄⁺ hydrolyses as a weak acid with Ka = Kw/Kb = 5.56 × 10⁻¹⁰. [H⁺] = √(Ka C) = √(5.56 × 10⁻¹²) = 2.36 × 10⁻⁶ M, so pH = 5.63. 8.37 is pOH-type confusion (14 − 5.63).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-78","question":"An acid–base indicator HIn has pKa = 5.0. The percentage of the indicator present in its basic form In⁻ at pH 6.0 is about:","options":["9.1%","90.9%","50%","99%"],"answer":1,"explanation":"pH = pKa + log([In⁻]/[HIn]) gives [In⁻]/[HIn] = 10^(6 − 5) = 10. Fraction as In⁻ = 10/11 = 90.9%. 9.1% is the fraction left as HIn, and 99% would correspond to pH 7.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-79","question":"100 mL of 0.1 M aqueous NH₃ is mixed with 50 mL of 0.1 M HCl. The pH of the resulting solution is (pKb of NH₃ = 4.74):","options":["4.74","5.28","9.26","11.13"],"answer":2,"explanation":"HCl (5 mmol) converts half of the NH₃ (10 mmol) to NH₄⁺, leaving 5 mmol each: a buffer at half-neutralisation, so pOH = pKb = 4.74 and pH = 9.26. Answering 4.74 forgets to convert pOH to pH.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-80", "question": "Solid ammonium carbamate dissociates in a closed vessel: NH₂COONH₄(s) ⇌ 2NH₃(g) + CO₂(g). If the total pressure at equilibrium is 3 atm, Kp is:", "options": ["27 atm³", "3 atm³", "0.148 atm³", "4 atm³"], "answer": 3, "explanation": "The gases form in a 2 : 1 ratio, so p(NH₃) = 2 atm and p(CO₂) = 1 atm. Kp = (2)² × 1 = 4 atm³ (in general Kp = 4P³/27). 27 comes from cubing the total pressure.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-81","question":"For H₂SO₄ the first ionisation is complete and Ka₂ (for HSO₄⁻) = 1.2 × 10⁻². The pH of 0.10 M H₂SO₄ is about:","options":["0.96","0.70","1.00","0.85"],"answer":0,"explanation":"Start with [H⁺] = [HSO₄⁻] = 0.10 M; then x(0.10 + x)/(0.10 − x) = 0.012 gives x ≈ 0.0098 M. [H⁺] = 0.1098 M, pH = 0.96. Treating H₂SO₄ as fully diprotic gives 0.70, and ignoring the second step gives 1.00; the common H⁺ strongly suppresses the second ionisation.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-82","question":"The molar solubility of AgCl in 1.0 M aqueous NH₃ is about (Ksp of AgCl = 1.8 × 10⁻¹⁰; formation constant of [Ag(NH₃)₂]⁺ = 1.6 × 10⁷):","options":["1.3 × 10⁻⁵ M","0.048 M","2.9 × 10⁻³ M","0.054 M"],"answer":1,"explanation":"AgCl + 2NH₃ ⇌ [Ag(NH₃)₂]⁺ + Cl⁻ has K = Ksp × Kf = 2.88 × 10⁻³. s²/(1 − 2s)² = K gives s/(1 − 2s) = 0.0537, so s = 0.048 M. 0.054 M neglects the NH₃ used up, and 1.3 × 10⁻⁵ M is the solubility in pure water.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-chemical-equilibrium-83", "question": "At 90 °C the ionic product of water is Kw = 1 × 10⁻¹². The pH of 0.01 M NaOH at this temperature, and the pH of neutral water at this temperature, are respectively:", "options": ["12 and 7", "10 and 6", "12 and 6", "10 and 7"], "answer": 1, "explanation": "pKw = 12, so neutral water has pH = 6. For 0.01 M NaOH, pOH = 2 and pH = pKw − pOH = 12 − 2 = 10. Using 14 for pKw (valid only at 25 °C) gives the trap 12 and 7.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-84", "question": "For a 1.0 × 10⁻⁶ M solution of acetic acid (Ka = 1.8 × 10⁻⁵) at 25 °C, which statement is correct?", "options": ["pH ≈ 6.0 and the acid is about 95% dissociated", "pH ≈ 5.4, from [H⁺] = √(Ka·C)", "pH ≈ 7.0 because the acid is too dilute to matter", "pH ≈ 6.0 but the acid is only about 1% dissociated"], "answer": 0, "explanation": "When C is far below Ka the acid is almost fully dissociated: solving x²/(C − x) = Ka (with water's contribution) gives α ≈ 0.95 and [H⁺] ≈ 9.6 × 10⁻⁷ M, pH ≈ 6.02. The shortcut √(Ka·C) gives 4.2 × 10⁻⁶ M, more H⁺ than the acid contains, so it is invalid here (dilution increases α).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-chemical-equilibrium-85", "question": "The pH of 0.10 M Na₂CO₃ at 25 °C is about (for H₂CO₃: Ka₁ = 4.3 × 10⁻⁷, Ka₂ = 4.7 × 10⁻¹¹):", "options": ["9.68", "13.0", "11.66", "12.3"], "answer": 2, "explanation": "CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻ has Kh = Kw/Ka₂ = 2.13 × 10⁻⁴ (the conjugate acid of CO₃²⁻ is HCO₃⁻, so Ka₂ is the right constant). [OH⁻] = √(2.13 × 10⁻⁵) = 4.6 × 10⁻³ M, pOH = 2.34, pH = 11.66. Using Ka₁ gives 9.68.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-86", "question": "1 mol of N₂O₄ in a 1 L flask is 50% dissociated at equilibrium (N₂O₄ ⇌ 2NO₂). The flask volume is then halved at the same temperature. The new degree of dissociation is about:", "options": ["0.25", "0.50", "0.71", "0.39"], "answer": 3, "explanation": "Kc = [NO₂]²/[N₂O₄] = 1²/0.5 = 2 mol/L. In 0.5 L: (2x/0.5)²/((1 − x)/0.5) = 2 → 4x² + x − 1 = 0 → x = (−1 + √17)/8 = 0.39. Compression lowers α (Le Chatelier), but not to the 0.25 a simple 'halve it' guess gives.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-87","question":"Two solids decompose in the same evacuated vessel at the same temperature: A(s) ⇌ B(g) + C(g), Kp₁ = 4 atm², and D(s) ⇌ B(g) + E(g), Kp₂ = 5 atm². The total pressure at equilibrium is:","options":["6 atm","4.24 atm","9 atm","3 atm"],"answer":0,"explanation":"B is common, so p_B = p_C + p_E. Multiplying by p_B: p_B² = Kp₁ + Kp₂ = 9, p_B = 3 atm, p_C = 4/3 and p_E = 5/3 atm. Total = 3 + 3 = 6 atm. 3 atm is only p_B, and 9 atm mistakes Kp₁ + Kp₂ (in atm²) for a pressure.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-chemical-equilibrium-88", "question": "A solution is 0.01 M in Fe³⁺ and 0.1 M in Mg²⁺ (Ksp: Fe(OH)₃ = 1 × 10⁻³⁸, Mg(OH)₂ = 1 × 10⁻¹¹). Fe³⁺ is considered completely precipitated when its concentration falls to 1 × 10⁻⁵ M. The pH range in which Fe³⁺ is completely precipitated while Mg²⁺ stays fully in solution is:", "options": ["2 to 9", "3 to 9", "3 to 10", "2 to 11"], "answer": 1, "explanation": "Complete Fe(OH)₃ precipitation: [OH⁻]³ = 10⁻³⁸/10⁻⁵ = 10⁻³³, [OH⁻] = 10⁻¹¹, pH = 3. Mg(OH)₂ begins to form when [OH⁻]² = 10⁻¹¹/0.1 = 10⁻¹⁰, [OH⁻] = 10⁻⁵, pH = 9. So pH 3–9; pH 2 is only where Fe(OH)₃ starts to precipitate.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-chemical-equilibrium-89", "question": "Assertion (A): For phosphoric acid, Ka₁ ≫ Ka₂ ≫ Ka₃. Reason (R): Each successive proton has to be removed from a species carrying a greater negative charge, which holds the proton more strongly.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Ka₁ ≈ 7 × 10⁻³, Ka₂ ≈ 6 × 10⁻⁸, Ka₃ ≈ 5 × 10⁻¹³: each step is about 10⁵ times weaker because H⁺ must leave H₂PO₄⁻, then HPO₄²⁻, whose growing negative charge attracts it. R explains A.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-90","question":"For H₂(g) + I₂(g) ⇌ 2HI(g), Kc = 4 at a certain temperature, and a 1 L vessel at equilibrium contains 1 mol H₂, 1 mol I₂ and 2 mol HI. 1 mol of H₂ is now added. The amount of HI at the new equilibrium is:","options":["2.0 mol","2.2 mol","2.4 mol","3.0 mol"],"answer":2,"explanation":"Let y mol of I₂ react: (2 + 2y)² = 4(2 − y)(1 − y) → 4 + 8y + 4y² = 8 − 12y + 4y² → y = 0.2. HI = 2.4 mol (H₂ 1.8, I₂ 0.8; check 2.4²/(1.8 × 0.8) = 4). Assuming the added H₂ reacts until I₂ is used up gives 4 mol, far too much.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-91","question":"A solution is 0.1 M in a weak acid HA (Ka = 1 × 10⁻⁵) and also 0.1 M in another weak acid HB (Ka = 4 × 10⁻⁵). The pH of the solution is about (log 5 = 0.70):","options":["3.00","2.70","2.85","2.65"],"answer":3,"explanation":"Both acids supply H⁺ to the same pool: [H⁺]² ≈ Ka(HA)·C + Ka(HB)·C = 1 × 10⁻⁶ + 4 × 10⁻⁶ = 5 × 10⁻⁶, so [H⁺] = 2.24 × 10⁻³ M and pH = 2.65. Using only the stronger acid HB (√(4 × 10⁻⁶) = 2 × 10⁻³ M) gives 2.70, and only HA gives 3.00.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-92","question":"For PCl₅(g) ⇌ PCl₃(g) + Cl₂(g), Kc = 0.04 mol/L at a certain temperature. A 1 L flask initially contains 0.20 mol PCl₅, 0.10 mol PCl₃ and 0.10 mol Cl₂. At equilibrium the amount of PCl₅ is about:","options":["0.209 mol","0.200 mol","0.191 mol","0.225 mol"],"answer":0,"explanation":"Q = (0.1 × 0.1)/0.2 = 0.05 > Kc, so the reaction runs backwards. (0.1 − x)²/(0.2 + x) = 0.04 → x² − 0.24x + 0.002 = 0 → x = 0.0086, so PCl₅ = 0.209 mol. Assuming the forward direction gives 0.191 mol.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-93","question":"A solution 0.01 M in Zn²⁺ is saturated with H₂S ([H₂S] = 0.1 M; Ka₁·Ka₂ = 1 × 10⁻²¹). If Ksp of ZnS is taken as 1 × 10⁻²¹, the minimum [H⁺] needed to prevent precipitation of ZnS is about:","options":["0.001 M","0.032 M","0.10 M","0.010 M"],"answer":1,"explanation":"Maximum allowed [S²⁻] = Ksp/[Zn²⁺] = 10⁻¹⁹ M. From [S²⁻] = Ka₁Ka₂[H₂S]/[H⁺]²: [H⁺]² = 10⁻²¹ × 0.1/10⁻¹⁹ = 10⁻³, so [H⁺] = 0.032 M. Forgetting to take the square root gives 0.001 M.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-chemical-equilibrium-94", "question": "How many of the following statements are correct? (A) For any conjugate acid–base pair in water, Ka × Kb = Kw. (B) pKa + pKb = 14 for a conjugate pair at all temperatures. (C) The stronger an acid, the weaker its conjugate base. (D) HClO₄ and HCl, equally strong in water, can be distinguished in strength in glacial acetic acid as solvent.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A ✓; C ✓; D ✓ (water levels all strong acids to H₃O⁺, whereas weakly basic acetic acid differentiates them, HClO₄ being stronger). B is false: pKa + pKb = pKw, which equals 14 only at 25 °C. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-95","question":"Water vapour dissociates slightly at high temperature: 2H₂O(g) ⇌ 2H₂(g) + O₂(g). If α (≪ 1) is the degree of dissociation at total pressure P, Kp is approximately:","options":["α²P/2","α³P","α³P/2","2α³P"],"answer":2,"explanation":"Per mole of H₂O: H₂O 1 − α, H₂ α, O₂ α/2; total ≈ 1 when α ≪ 1. Kp = (αP)²(αP/2)/((1 − α)P)² ≈ α³P/2. Forgetting the O₂ term's 1/2 gives α³P.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-96","question":"Assuming both protons ionise completely, the pH of 0.005 M H₂SO₄ at 25 °C is:","options":["2.3","2.0","1.7","3.0"],"answer":1,"explanation":"[H⁺] = 2 × 0.005 = 0.01 M, so pH = −log(0.01) = 2.0. Treating the acid as monobasic gives [H⁺] = 0.005 M and pH 2.3.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-chemical-equilibrium-97","question":"Which of the following salts gives an acidic aqueous solution at 25 °C?","options":["NH₄NO₃","NaCN","CH₃COOK","KCl"],"answer":0,"explanation":"NH₄NO₃ is the salt of a weak base and a strong acid; NH₄⁺ hydrolyses (NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺) and makes the solution acidic. KCl is neutral, while NaCN and CH₃COOK are basic because their anions hydrolyse.","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-equilibrium-98","question":"For H₂(g) + I₂(g) ⇌ 2HI(g), Kc = 64 at a certain temperature. At the same temperature, Kc for HI(g) ⇌ ½H₂(g) + ½I₂(g) is:","options":["0.25","8","0.0156","0.125"],"answer":3,"explanation":"Reversing the reaction inverts K (1/64), and halving the coefficients takes its square root: K = (1/64)^½ = 1/8 = 0.125. 0.0156 = 1/64 only reverses the equation.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-99","question":"40 mL of 0.1 M NaOH is mixed with 60 mL of 0.1 M HCl at 25 °C. The pH of the resulting solution is about (log 2 = 0.30):","options":["2.00","1.40","1.70","1.30"],"answer":2,"explanation":"HCl = 6 mmol, NaOH = 4 mmol; excess H⁺ = 2 mmol in 100 mL = 0.02 M. pH = −log(0.02) = 2 − 0.30 = 1.70. Forgetting the dilution to 100 mL (2 mmol in 60 mL) gives a lower pH.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-100","question":"For the heterogeneous equilibrium C(s) + H₂O(g) ⇌ CO(g) + H₂(g), the relation between Kp and Kc is:","options":["Kp = Kc(RT)²","Kp = Kc(RT)","Kp = Kc(RT)⁻¹","Kp = Kc"],"answer":1,"explanation":"Only gaseous species count in Δn_g: products 2 mol gas, reactants 1 mol gas (carbon is a solid), so Δn_g = +1 and Kp = Kc(RT)¹. Counting C(s) as a gas would wrongly give Δn_g = 0.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-101","question":"The molar solubility of CaF₂ (Ksp = 3.4 × 10⁻¹¹) in 0.1 M NaF solution is about:","options":["3.4 × 10⁻⁹ M","1.7 × 10⁻¹⁰ M","3.4 × 10⁻¹⁰ M","2.0 × 10⁻⁴ M"],"answer":0,"explanation":"[F⁻] ≈ 0.1 M from NaF (the common ion), so s = Ksp/[F⁻]² = 3.4 × 10⁻¹¹/0.01 = 3.4 × 10⁻⁹ M. Forgetting to square [F⁻] gives 3.4 × 10⁻¹⁰ M; 2.0 × 10⁻⁴ M is the solubility in pure water.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-102","question":"For 2NO₂(g) ⇌ N₂O₄(g), ΔH° < 0. The yield of N₂O₄ at equilibrium is increased by:","options":["Raising the temperature and raising the pressure","Lowering the temperature and lowering the pressure","Adding a catalyst at constant temperature","Lowering the temperature and raising the pressure"],"answer":3,"explanation":"The forward reaction is exothermic, so lowering T favours it; it also reduces the number of gas moles (2 → 1), so raising P favours it. A catalyst only speeds up attainment of equilibrium and does not change the yield.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-chemical-equilibrium-103","question":"1 L of a buffer is 0.20 M in a weak acid HA (pKa = 4.76) and 0.20 M in NaA. After 0.05 mol of solid NaOH is dissolved in it (no volume change), the pH is about (log 5/3 = 0.22):","options":["5.24","4.54","4.98","4.76"],"answer":2,"explanation":"OH⁻ converts HA to A⁻: HA = 0.15 mol, A⁻ = 0.25 mol. pH = pKa + log(0.25/0.15) = 4.76 + 0.22 = 4.98. 4.54 results from subtracting the log term (treating NaOH as if it were an acid).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-104","question":"For H₃PO₄, pKa₁ = 2.15, pKa₂ = 7.20 and pKa₃ = 12.35. The pH of a 0.1 M Na₂HPO₄ solution is about:","options":["12.35","9.78","4.68","7.20"],"answer":1,"explanation":"HPO₄²⁻ is amphiprotic and lies between the 2nd and 3rd ionisations, so pH ≈ (pKa₂ + pKa₃)/2 = (7.20 + 12.35)/2 = 9.78, nearly independent of concentration. 4.68 is the value for NaH₂PO₄, which uses pKa₁ and pKa₂.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-chemical-equilibrium-105","question":"Solid NaHCO₃ is heated in a closed evacuated vessel: 2NaHCO₃(s) ⇌ Na₂CO₃(s) + CO₂(g) + H₂O(g). At equilibrium the total pressure is 0.50 atm. Kp for the reaction is:","options":["0.0625 atm²","0.25 atm²","0.125 atm²","0.50 atm"],"answer":0,"explanation":"CO₂ and H₂O are formed in equal amounts, so each has a partial pressure of 0.25 atm. The solids are excluded, so Kp = p(CO₂) × p(H₂O) = 0.25 × 0.25 = 0.0625 atm². 0.25 atm² wrongly squares the total pressure.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-106","question":"PCl₅ (molar mass 208.5) dissociates as PCl₅(g) ⇌ PCl₃(g) + Cl₂(g). At a certain temperature the vapour density of the equilibrium mixture is 80.2. The degree of dissociation of PCl₅ is about:","options":["0.70","0.43","0.23","0.30"],"answer":3,"explanation":"Theoretical vapour density D = 208.5/2 = 104.25. For one mole giving two, α = (D − d)/d = (104.25 − 80.2)/80.2 ≈ 0.30. Dividing by D instead of d gives 0.23.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-107","question":"50 mL of 0.1 M aqueous NH₃ (pKb = 4.74) is titrated with 0.1 M HCl. The pH after 75% of the base has been neutralised is about (log 3 = 0.48):","options":["5.22","9.74","8.78","9.26"],"answer":2,"explanation":"Remaining NH₃ : NH₄⁺ = 25 : 75 = 1 : 3. pOH = pKb + log([NH₄⁺]/[NH₃]) = 4.74 + 0.48 = 5.22, so pH = 14 − 5.22 = 8.78. 9.74 reverses the ratio; 5.22 is the pOH.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-108","question":"A saturated aqueous solution of a sparingly soluble hydroxide M(OH)₃ has pH = 10.0 at 25 °C. The Ksp of M(OH)₃ is about:","options":["1.0 × 10⁻¹⁶","3.3 × 10⁻¹⁷","2.7 × 10⁻¹⁵","3.3 × 10⁻¹³"],"answer":1,"explanation":"pOH = 4, so [OH⁻] = 1 × 10⁻⁴ M and s = [M³⁺] = [OH⁻]/3 = 3.33 × 10⁻⁵ M. Ksp = [M³⁺][OH⁻]³ = 3.33 × 10⁻⁵ × 10⁻¹² = 3.3 × 10⁻¹⁷. Taking [M³⁺] = [OH⁻] gives 1.0 × 10⁻¹⁶.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-109","question":"1 mol of A and 2 mol of B are placed in a 2 L vessel and allowed to reach the equilibrium A(g) + 2B(g) ⇌ C(g). At equilibrium 0.4 mol of C is present. Kc is about:","options":["1.85 L² mol⁻²","3.70 L² mol⁻²","0.46 L² mol⁻²","0.93 L² mol⁻²"],"answer":0,"explanation":"At equilibrium A = 0.6 mol, B = 1.2 mol, C = 0.4 mol; concentrations in 2 L: 0.3, 0.6 and 0.2 M. Kc = 0.2/(0.3 × 0.6²) = 1.85 L² mol⁻². Using moles instead of concentrations gives 0.46.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-110","question":"10 mL of 1.0 × 10⁻³ M BaCl₂ is mixed with 40 mL of 1.0 × 10⁻⁴ M Na₂SO₄ (Ksp of BaSO₄ = 1.1 × 10⁻¹⁰). Which statement is correct?","options":["No precipitate forms, since the ions are too dilute after mixing","No precipitate forms, since the ionic product is 1.6 × 10⁻¹¹","A precipitate forms, since the ionic product is 1.0 × 10⁻⁷","A precipitate forms, since the ionic product is 1.6 × 10⁻⁸"],"answer":3,"explanation":"After mixing (50 mL), [Ba²⁺] = (10 × 10⁻³)/50 = 2.0 × 10⁻⁴ M and [SO₄²⁻] = 8.0 × 10⁻⁵ M. Ionic product = 1.6 × 10⁻⁸ > Ksp, so BaSO₄ precipitates. 1.0 × 10⁻⁷ ignores the dilution on mixing.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-111","question":"The pH of an aqueous solution of NH₄CN is about (pKa of HCN = 9.30, pKb of NH₃ = 4.75):","options":["4.73","7.00","9.28","11.65"],"answer":2,"explanation":"For a salt of a weak acid and a weak base, pH = 7 + ½(pKa − pKb) = 7 + ½(9.30 − 4.75) = 9.28, independent of concentration. CN⁻ hydrolyses more than NH₄⁺ because HCN is the weaker acid, so the solution is basic.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-112","question":"For COCl₂(g) ⇌ CO(g) + Cl₂(g), Kp = 0.25 atm at a certain temperature. When pure COCl₂ reaches equilibrium at a total pressure of 0.75 atm, its degree of dissociation is:","options":["0.33","0.50","0.58","0.25"],"answer":1,"explanation":"For AB ⇌ A + B, Kp = α²P/(1 − α²). So α² = Kp/(Kp + P) = 0.25/(0.25 + 0.75) = 0.25 and α = 0.50. Using Kp = α²P (neglecting 1 − α²) gives α ≈ 0.58.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-113","question":"The pH of 0.05 M NaCN at 25 °C is (Ka of HCN = 5 × 10⁻¹⁰):","options":["11.0","12.3","10.0","3.0"],"answer":0,"explanation":"Kh = Kw/Ka = 10⁻¹⁴/(5 × 10⁻¹⁰) = 2 × 10⁻⁵. [OH⁻] = √(Kh·C) = √(2 × 10⁻⁵ × 0.05) = 10⁻³ M, so pOH = 3 and pH = 11.0. 3.0 is the pOH, not the pH.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-114","question":"For 2NOCl(g) ⇌ 2NO(g) + Cl₂(g), Kc = 3.0 × 10⁻⁶ mol L⁻¹ at 700 K. Kp at this temperature is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["5.2 × 10⁻⁸ atm","3.0 × 10⁻⁶ atm","1.0 × 10⁻² atm","1.7 × 10⁻⁴ atm"],"answer":3,"explanation":"Δn_g = 3 − 2 = +1, so Kp = Kc(RT) = 3.0 × 10⁻⁶ × 0.0821 × 700 = 1.7 × 10⁻⁴ atm. Dividing by RT instead of multiplying gives 5.2 × 10⁻⁸.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-115","question":"A solution is 0.1 M in HA (Ka = 1 × 10⁻⁵) and 0.1 M in another weak acid HB (Ka = 4 × 10⁻⁵). Assuming both are weakly ionised, its pH is about:","options":["3.00","2.35","2.65","2.70"],"answer":2,"explanation":"Both acids share the same [H⁺]: [H⁺]² = Ka(HA)·C₁ + Ka(HB)·C₂ = 10⁻⁶ + 4 × 10⁻⁶ = 5 × 10⁻⁶, so [H⁺] = 2.24 × 10⁻³ M and pH = 2.65. 2.70 considers HB alone and 3.00 HA alone.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-116","question":"50 mL of 0.1 M H₃PO₄ (pKa₁ = 2.15, pKa₂ = 7.20, pKa₃ = 12.35) is titrated with 0.1 M NaOH. After 75 mL of NaOH has been added, the pH is about:","options":["9.78","7.20","4.68","2.15"],"answer":1,"explanation":"H₃PO₄ = 5 mmol and OH⁻ = 7.5 mmol: the first 5 mmol make 5 mmol H₂PO₄⁻, and the next 2.5 mmol convert half of it to HPO₄²⁻. With [H₂PO₄⁻] = [HPO₄²⁻] the solution is a buffer at pH = pKa₂ = 7.20. 4.68 is the first equivalence point (50 mL).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-chemical-equilibrium-117","question":"Na₂SO₄ is added slowly to a solution 0.1 M in both Ba²⁺ and Sr²⁺ (Ksp: BaSO₄ = 1 × 10⁻¹⁰, SrSO₄ = 3 × 10⁻⁷). When SrSO₄ just begins to precipitate, the percentage of the original Ba²⁺ still in solution is about:","options":["0.033%","3.3%","0.33%","0.0033%"],"answer":0,"explanation":"SrSO₄ starts to precipitate when [SO₄²⁻] = 3 × 10⁻⁷/0.1 = 3 × 10⁻⁶ M. Then [Ba²⁺] = 10⁻¹⁰/(3 × 10⁻⁶) = 3.3 × 10⁻⁵ M, which is 3.3 × 10⁻⁵/0.1 × 100 = 0.033% of the original. The separation is therefore almost complete.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-118","question":"Taking the ionisation of water into account, the pH of a 1.0 × 10⁻⁷ M HCl solution at 25 °C is about:","options":["6.70","6.85","7.00","6.79"],"answer":3,"explanation":"Charge balance: [H⁺] = 10⁻⁷ + Kw/[H⁺], so [H⁺]² − 10⁻⁷[H⁺] − 10⁻¹⁴ = 0, giving [H⁺] = 1.62 × 10⁻⁷ M and pH = 6.79. Simply adding 10⁻⁷ from water to 10⁻⁷ from HCl gives 2 × 10⁻⁷ (pH 6.70), which overcounts because the acid suppresses water's ionisation.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-119","question":"100 mL of 0.3 M NH₄Cl is mixed with 100 mL of 0.1 M NaOH at 25 °C (pKb of NH₃ = 4.74, log 2 = 0.30). The pH of the mixture is about:","options":["5.04","9.56","8.96","9.26"],"answer":2,"explanation":"OH⁻ (10 mmol) converts 10 mmol NH₄⁺ to NH₃, leaving 20 mmol NH₄⁺: a basic buffer. pOH = 4.74 + log(20/10) = 5.04, so pH = 8.96. 9.56 inverts the ratio, and 5.04 is the pOH.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-120","question":"The concentration of acetic acid (Ka = 1.8 × 10⁻⁵) that has the same pH as 1.0 × 10⁻³ M HCl is about:","options":["0.001 M","0.057 M","0.018 M","0.56 M"],"answer":1,"explanation":"Required [H⁺] = 10⁻³ M. For the weak acid, Ka = [H⁺][A⁻]/[HA] = (10⁻³)²/(C − 10⁻³), so C = 10⁻⁶/1.8 × 10⁻⁵ + 10⁻³ = 0.0556 + 0.001 ≈ 0.057 M. Taking C equal to the HCl concentration (0.001 M) ignores that a weak acid is only slightly ionised.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-121","question":"A sparingly soluble salt MA has Ksp = 1 × 10⁻¹⁰, and HA is a weak acid with Ka = 1 × 10⁻⁵. The molar solubility of MA in a solution buffered at pH 3 is about:","options":["1.0 × 10⁻⁴ M","1.0 × 10⁻³ M","3.2 × 10⁻⁵ M","1.0 × 10⁻⁵ M"],"answer":0,"explanation":"A⁻ released is partly protonated, so total dissolved A = [A⁻](1 + [H⁺]/Ka) = 101[A⁻]. Then s² = Ksp × 101, giving s ≈ 1.0 × 10⁻⁴ M, ten times the solubility in pure water (1 × 10⁻⁵ M). Acid increases the solubility of salts of weak acids.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-122","question":"25 mL of 0.2 M CH₃COOH (Ka = 1.8 × 10⁻⁵) is titrated with 0.2 M NaOH. The pH at the equivalence point is about:","options":["5.13","9.02","7.00","8.87"],"answer":3,"explanation":"At equivalence, 5 mmol CH₃COO⁻ is in 50 mL, so C = 0.1 M. Kh = 10⁻¹⁴/1.8 × 10⁻⁵ = 5.56 × 10⁻¹⁰ and [OH⁻] = √(Kh·C) = 7.45 × 10⁻⁶ M, so pOH = 5.13 and pH = 8.87. Ignoring the dilution (C = 0.2 M) gives 9.02.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-123","question":"How many of the following statements are correct? (A) Adding a catalyst changes the composition of an equilibrium mixture. (B) For an endothermic reaction, K increases with temperature. (C) Adding an inert gas at constant volume does not shift any gaseous equilibrium. (D) For a reaction with Δn_g = 0, changing the total pressure does not shift the equilibrium. (E) K for a reaction depends on the initial concentrations of the reactants.","options":["Only one","Only two","Only three","Only four"],"answer":2,"explanation":"(B), (C) and (D) are correct. (A) is false: a catalyst speeds up the forward and reverse reactions equally. (E) is false: K depends only on temperature for a given reaction. Three statements are correct.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-equilibrium-124","question":"1 mol of N₂O₄ is placed in a 5 L flask. At equilibrium (N₂O₄ ⇌ 2NO₂, Kc = 0.20 mol L⁻¹) its degree of dissociation is about:","options":["0.71","0.39","0.20","0.50"],"answer":1,"explanation":"[N₂O₄]₀ = 0.2 M. With x dissociated: Kc = (2x)²/(0.2 − x) = 0.20, so 4x² + 0.2x − 0.04 = 0, giving x = 0.078 M and α = 0.078/0.2 ≈ 0.39. Neglecting x in the denominator gives x = 0.1 and α = 0.5.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-equilibrium-125","question":"For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the equilibrium constant in terms of mole fractions, Kx, is related to Kp by Kp = Kx·P^Δn. If the total pressure is doubled at constant temperature, Kx becomes:","options":["4 times its original value","one quarter of its original value","2 times its original value","unchanged"],"answer":0,"explanation":"Δn = 2 − 4 = −2, so Kx = Kp·P². Kp is fixed at constant T, so doubling P makes Kx four times larger, i.e. the mixture shifts towards NH₃. Kp and Kc stay unchanged; only Kx depends on pressure.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-126","question":"How many grams of NaOH (molar mass 40) must be added to 1 L of 0.1 M acetic acid (pKa = 4.74) to give a buffer of pH 5.00? (10⁰·²⁶ = 1.82)","options":["1.82 g","4.00 g","1.42 g","2.58 g"],"answer":3,"explanation":"NaOH (x mol) converts acid to acetate: [A⁻]/[HA] = x/(0.1 − x) = 10^(5.00 − 4.74) = 1.82. So x = 0.182/2.82 = 0.0645 mol = 2.58 g. 1.42 g is the remaining acid (0.0355 mol) mistaken for the base added.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-equilibrium-127","question":"A diprotic acid H₂A has pKa₁ = 2.8 and pKa₂ = 5.7. At what pH are the concentrations of H₂A and A²⁻ equal?","options":["5.70","8.50","4.25","2.80"],"answer":2,"explanation":"Multiplying the two dissociation expressions gives Ka₁Ka₂ = [H⁺]²[A²⁻]/[H₂A]. When [H₂A] = [A²⁻], [H⁺]² = Ka₁Ka₂, so pH = (pKa₁ + pKa₂)/2 = 4.25. At pH 2.8 it is [H₂A] = [HA⁻], and at 5.7 [HA⁻] = [A²⁻].","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-equilibrium-128","question":"At a certain temperature K₁ = 4 × 10⁻⁶ for N₂(g) + O₂(g) ⇌ 2NO(g) and K₂ = 1 × 10⁴ for 2NO(g) + O₂(g) ⇌ 2NO₂(g). The equilibrium constant for NO₂(g) ⇌ ½N₂(g) + O₂(g) at this temperature is:","options":["0.04","5","0.2","25"],"answer":1,"explanation":"Adding the two reactions gives N₂ + 2O₂ ⇌ 2NO₂ with K = K₁K₂ = 0.04. The required reaction is the reverse, halved, so K = (1/0.04)^½ = 5. 0.2 forgets to invert, and 25 forgets to take the square root.","difficulty":"very-hard","source":"JEE Main pattern"},
];

